// كتاب تجريبي من نوع «المتن أعلى الصفحة ثم ــ ثم الشرح» بصيغة تراث الحقيقية
// (صفحات مأخوذة من «شرح ثلاثة الأصول» للعثيمين id=11257 مع حالات مركّبة)
import fs from 'node:fs';

const LONG =
  'والعمل في الحقيقة هو ثمرة العلم، فمن عمل بلا علم فقد شابه النصارى، ومن علم ولم يعمل فقد شابه اليهود، والمقصود أن يجمع الإنسان بين العلم والعمل، فإن العلم بلا عمل كالشجر بلا ثمر، وقد كان السلف يحرصون على العمل بما يعلمون حرصاً شديداً، حتى قال بعضهم: كنا نستعين على حفظ الحديث بالعمل به. ';

const t = (id, n) => `<span data-type="title" id=toc-${id}>${n}</span>`;
const pages = [
  // ١) مقدمة فيها اسم الكتاب والمؤلف والمحقق (تُحذف آلياً)
  '...\nشرح ثلاثة الأصول\nتأليف: محمد بن صالح العثيمين\nتحقيق: فهد بن ناصر السليمان\nبسم الله الرحمن الرحيم\nالحمد لله رب العالمين، والصلاة والسلام على نبينا محمد وعلى آله وصحبه أجمعين، أما بعد: فهذا شرح مختصر لرسالة ثلاثة الأصول.',
  // ٢) متن + ــ في آخر السطر + شرح مرقم
  t(27, 'معنى الرب والدليل على ذلك') + '\n...\nفَإِذَا قِيلَ لَكَ: مَنْ رَبُّكَ (١)؟ فَقُلْ: رَبِّيَ اللهُ الَّذِي رَبَّانِي وَرَبَّى جَمِيعَ الْعَالَمِينَ بِنِعَمِهِ (٢)،.... ــ\n(١) أي من هو ربك الذي خلقك، وأمدك، وأعدك، ورزقك.\n(٢) التربية هي عبارة عن الرعاية التي يكون بها تقويم المربى، ويشعر',
  // ٣) نقاط = استكمال المتن السابق، والشرح يكمل
  '. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\nــ\nبها قوله: «ربانا» ويشعر بأن أحق من يتوجه إليه الإنسان بالعبادة هو الرب جل وعلا. ' + LONG.repeat(3),
  // ٤) متن ثم ــ وحده ثم شرح طويل ثم ــ ثانٍ = حاشية
  t(8, 'المسألة الثانية العمل به') + '\n...\nالثانية العمل به (١) . . . . . . . . . . . . . . . . . .\nــ\n(١) قوله العمل به أي العمل بما تقتضيه هذه المعرفة من الإيمان بالله والقيام بطاعته (١) بامتثال أوامره واجتناب نواهيه.\n' + LONG.repeat(5) + '\nــ\n(١) انظر: الأصول الثلاثة، ص ١٢.',
  // ٥) صفحة شرح بلا متن جديد
  t(11, 'أقسام الصبر') + '\n...\nــ\nوالصبر ثلاثة أقسام:\n١-صبر على طاعة الله.\n٢-صبر عن محارم الله.\n٣-صبر على أقدار الله التي يجريها إما مما لا كسب للعباد فيه، وإما مما يجريه الله على أيدي بعض العباد من الإيذاء والاعتداء.',
  // ٦) متن جديد
  'وَالدَّلِيلُ قَوْلُهُ تَعَالَى: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ (١) وَكُلُّ مَا سِوَى اللهِ عَالَمٌ، وَأَنَا وَاحِدٌ مِنْ ذَلِكَ الْعَالَمِ (٢). ــ\n(١) الحمد: وصف المحمود بالكمال مع المحبة والتعظيم.\n(٢) أي أن كل ما سوى الله فهو عالم، وسموا عالماً لأنهم علم على خالقهم ومالكهم ومدبرهم.',
];

const meta = (i) => JSON.stringify({ headings: [], page_id: i, page: i + 20, vol: '1', book_name: 'شرح ثلاثة الأصول للعثيمين', author_name: 'ابن عثيمين' });
const book = {
  meta: {
    id: 11257,
    name: 'شرح ثلاثة الأصول للعثيمين',
    info: 'الكتاب: شرح ثلاثة الأصول\nالمؤلف: محمد بن صالح بن محمد العثيمين (ت ١٤٢١هـ)\nالمحقق: فهد بن ناصر السليمان\nالناشر: دار الثريا للنشر\nالطبعة: الرابعة، ١٤٢٤هـ',
  },
  indexes: {
    headings: [
      { title: 'معنى الرب والدليل على ذلك', level: 2, page: 2 },
      { title: 'المسألة الثانية العمل به', level: 3, page: 4 },
      { title: 'أقسام الصبر', level: 3, page: 5 },
    ],
    volume_bounds: { 1: [1, pages.length] },
    page_map: pages.map((_, i) => `1,${i + 21}`),
  },
};
fs.writeFileSync(
  new URL('./book-split.json', import.meta.url),
  JSON.stringify({ book, pages: pages.map((text, i) => ({ page_id: i + 1, text, meta: meta(i + 1) })) }, null, 1),
);
console.log('split fixture pages:', pages.length);
